SET NAMES utf8mb4;
START TRANSACTION;

INSERT IGNORE INTO terms (academic_year, term, is_current, is_published, published_at) VALUES
  (2566, 0, 0, 1, NOW()),
  (2567, 0, 0, 1, NOW()),
  (2568, 0, 0, 1, NOW());
UPDATE terms SET is_published = 1, published_at = COALESCE(published_at, NOW())
 WHERE term = 0 AND academic_year IN (2566, 2567, 2568);

